-- R-01.2: the ingredient catalog (490 ingredients in en-US, en-GB, en-AU).
-- Generated by scripts/catalog-seed.js from supabase/catalog/ingredients.json. Don't edit:
-- change the JSON and generate a new migration.

on conflict (id) do update set
  default_dimension = excluded.default_dimension,
  density_g_per_ml = excluded.density_g_per_ml,
  section_id = excluded.section_id,
  allergen_codes = excluded.allergen_codes,
  is_default_staple = excluded.is_default_staple,
  deleted_at = null;

on conflict (ingredient_id, locale) do update set
  name = excluded.name,
  plural = excluded.plural,
  synonyms = excluded.synonyms,
  deleted_at = null;

-- Catalog items dropped from the JSON are soft-deleted, so recipes that use them keep working.
update public.ingredients set deleted_at = now()
where household_id is null and deleted_at is null and id <> all (array['ingredient.onion', 'ingredient.red_onion', 'ingredient.white_onion', 'ingredient.shallot', 'ingredient.scallion', 'ingredient.leek', 'ingredient.garlic', 'ingredient.garlic_bulb', 'ingredient.ginger', 'ingredient.potato', 'ingredient.baby_potato', 'ingredient.sweet_potato', 'ingredient.carrot', 'ingredient.celery', 'ingredient.celeriac', 'ingredient.parsnip', 'ingredient.beet', 'ingredient.turnip', 'ingredient.rutabaga', 'ingredient.radish', 'ingredient.fennel', 'ingredient.tomato', 'ingredient.cherry_tomato', 'ingredient.cucumber', 'ingredient.bell_pepper', 'ingredient.jalapeno', 'ingredient.chili_pepper', 'ingredient.zucchini', 'ingredient.eggplant', 'ingredient.butternut_squash', 'ingredient.pumpkin', 'ingredient.spaghetti_squash', 'ingredient.broccoli', 'ingredient.broccolini', 'ingredient.cauliflower', 'ingredient.cabbage', 'ingredient.red_cabbage', 'ingredient.napa_cabbage', 'ingredient.bok_choy', 'ingredient.brussels_sprout', 'ingredient.kale', 'ingredient.spinach', 'ingredient.swiss_chard', 'ingredient.lettuce', 'ingredient.romaine', 'ingredient.mixed_greens', 'ingredient.arugula', 'ingredient.watercress', 'ingredient.asparagus', 'ingredient.green_bean', 'ingredient.snow_pea', 'ingredient.pea', 'ingredient.corn', 'ingredient.mushroom', 'ingredient.portobello', 'ingredient.shiitake', 'ingredient.avocado', 'ingredient.artichoke', 'ingredient.okra', 'ingredient.bean_sprout', 'ingredient.basil', 'ingredient.cilantro', 'ingredient.parsley', 'ingredient.mint', 'ingredient.dill', 'ingredient.chives', 'ingredient.rosemary', 'ingredient.thyme', 'ingredient.sage', 'ingredient.oregano_fresh', 'ingredient.lemongrass', 'ingredient.apple', 'ingredient.pear', 'ingredient.banana', 'ingredient.orange', 'ingredient.mandarin', 'ingredient.lemon', 'ingredient.lime', 'ingredient.grapefruit', 'ingredient.grape', 'ingredient.strawberry', 'ingredient.blueberry', 'ingredient.raspberry', 'ingredient.blackberry', 